/* eslint-disable no-undefined */
import { useCallback, useRef, useState } from 'react';

// Heavily inspired by https://github.com/adobe/react-spectrum
export default function useControllableState({
  prop: value,
  defaultProp: defaultValue,
  onChange = () => {}
}) {
  const [stateValue, setStateValue] = useState(value || defaultValue);
  const ref = useRef(value !== undefined);
  const wasControlled = ref.current;
  const isControlled = value !== undefined;
  // Internal state reference for useCallback
  const stateRef = useRef(stateValue);
  if (wasControlled !== isControlled) {
    // eslint-disable-next-line max-len, no-console
    console.warn(`WARN: A component changed from ${wasControlled ? 'controlled' : 'uncontrolled'} to ${isControlled ? 'controlled' : 'uncontrolled'}.`);
  }
  ref.current = isControlled;
  const setValue = useCallback((value, ...args) => {
    const onChangeCaller = (value, ...onChangeArgs) => {
      if (onChange) {
        if (!Object.is(stateRef.current, value)) {
          onChange(value, ...onChangeArgs);
        }
      }
      if (!isControlled) {
        stateRef.current = value;
      }
    };
    if (typeof value === 'function') {
      // eslint-disable-next-line max-len, no-console
      console.warn('We can not support a function callback. See Github Issues for details https://github.com/adobe/react-spectrum/issues/2320');
      // this supports functional updates https://reactjs.org/docs/hooks-reference.html#functional-updates
      // when someone using useControlledState calls setControlledState(myFunc)
      // this will call our useState setState with a function as well which invokes myFunc and calls onChange with
      // the value from myFunc if we're in an uncontrolled state, then we also return the value of myFunc which to
      // setState looks as though it was just called with myFunc from the beginning otherwise we just return the
      // controlled value, which won't cause a rerender because React knows to bail out when the value is the same
      const updateFunction = (oldValue, ...functionArgs) => {
        const interceptedValue = value(isControlled ? stateRef.current : oldValue, ...functionArgs);
        onChangeCaller(interceptedValue, ...args);
        if (!isControlled) {
          return interceptedValue;
        }
        return oldValue;
      };
      setStateValue(updateFunction);
    } else {
      if (!isControlled) {
        setStateValue(value);
      }
      onChangeCaller(value, ...args);
    }
  }, [isControlled, onChange]);
  // If a controlled component's value prop changes, we need to update stateRef
  if (isControlled) {
    stateRef.current = value;
  } else {
    value = stateValue;
  }
  return [value, setValue];
}