/**
 * Each key is a named level of density.
 * Each factor is a number which is multiplied against
 *  the grid unit (intents.ux.box.density) value which determines the space.
 */
export const UX_SPACE_AS = {
  module: {
    paddingFactor: 8,
    gapFactor: 3
  },
  block: {
    paddingFactor: 5,
    gapFactor: 3
  },
  lockup: {
    paddingFactor: 2,
    gapFactor: 1
  }
};
export const UX_SPACE_SIZE = {
  sm: {
    paddingFactor: 1,
    gapFactor: 1
  },
  md: {
    paddingFactor: 2,
    gapFactor: 2
  },
  lg: {
    paddingFactor: 3,
    gapFactor: 3
  },
  xl: {
    paddingFactor: 5,
    gapFactor: 5
  }
};
export const asOptions = Object.keys(UX_SPACE_AS).reduce((acc, key) => ({
  [key.toUpperCase()]: key,
  ...acc
}), []);
export const sizeOptions = Object.keys(UX_SPACE_SIZE).reduce((acc, key) => ({
  [key.toUpperCase()]: key,
  ...acc
}), []);